<html lang="pl">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <meta name="csrf-token" content="{{ csrf_token() }}">
    <title>@yield('title', 'Panel Ewy') · Ewa Kwiecień</title>
    <style>
        :root{--ink:#1f302b;--muted:#75827c;--green:#315d4f;--green-dark:#23493e;--mint:#e8f1eb;--cream:#f6f7f2;--line:#e6eae4;--white:#fff;--gold:#edc77a;--red:#b94435;--shadow:0 20px 60px rgba(34,61,49,.08)}
        *{box-sizing:border-box}body{margin:0;background:var(--cream);color:var(--ink);font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;font-size:15px;line-height:1.5}a{color:inherit;text-decoration:none}button,input,textarea{font:inherit}.shell{min-height:100vh;display:grid;grid-template-columns:250px minmax(0,1fr)}.sidebar{background:#fff;border-right:1px solid var(--line);padding:30px 20px;display:flex;flex-direction:column;gap:38px}.brand{display:flex;align-items:center;gap:12px;padding:0 8px}.brand-mark{width:40px;height:40px;border-radius:14px;background:var(--green);display:grid;place-items:center;color:#fff;font-size:21px}.brand-name{font-weight:750;letter-spacing:-.03em;font-size:16px}.brand-caption{display:block;color:var(--muted);font-size:12px;font-weight:500;letter-spacing:0}.nav-label{font-size:10px;color:#99a39d;font-weight:750;letter-spacing:.13em;text-transform:uppercase;padding:0 11px;margin-bottom:9px}.nav{display:grid;gap:5px}.nav a{display:flex;align-items:center;gap:12px;padding:11px 12px;border-radius:12px;color:#65736c;font-weight:600;font-size:14px;transition:.18s}.nav a:hover,.nav a.active{background:var(--mint);color:var(--green)}.nav-icon{width:20px;text-align:center;font-size:17px}.sidebar-bottom{margin-top:auto;border-top:1px solid var(--line);padding:20px 8px 0}.workspace-label{font-size:12px;color:var(--muted)}.workspace-name{font-weight:650;font-size:13px;margin-top:3px}.main{min-width:0}.topbar{height:82px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 clamp(24px,5vw,70px);background:rgba(255,255,255,.68)}.top-eyebrow{font-size:12px;color:var(--muted)}.top-title{font-weight:650;font-size:14px}.account{display:flex;align-items:center;gap:12px}.avatar{display:grid;place-items:center;background:#edf0e8;color:var(--green);width:38px;height:38px;border-radius:50%;font-weight:700;font-size:13px}.account-text{font-weight:650;font-size:13px}.account-sub{font-size:11px;color:var(--muted)}.logout{margin-left:15px;background:none;border:0;color:#68776f;font-size:13px;font-weight:600;cursor:pointer}.content{max-width:1150px;margin:0 auto;padding:48px clamp(24px,5vw,70px) 72px}.eyebrow{display:flex;align-items:center;gap:8px;color:var(--green);font-size:12px;font-weight:750;text-transform:uppercase;letter-spacing:.12em}.eyebrow:before{content:"";width:18px;height:1px;background:var(--gold)}h1{font-size:clamp(29px,4vw,40px);line-height:1.15;letter-spacing:-.045em;margin:13px 0 10px;font-weight:720}.lede{color:var(--muted);font-size:15px;margin:0;max-width:600px}.intro{display:flex;justify-content:space-between;align-items:flex-end;gap:20px;margin-bottom:36px}.button{display:inline-flex;align-items:center;justify-content:center;gap:8px;background:var(--green);color:#fff;border:0;border-radius:10px;padding:12px 17px;font-size:13px;font-weight:680;cursor:pointer;transition:.18s}.button:hover{background:var(--green-dark);transform:translateY(-1px)}.button.secondary{background:#fff;color:var(--green);border:1px solid var(--line)}.button.secondary:hover{background:var(--mint)}.cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.card{position:relative;min-height:250px;border:1px solid var(--line);background:#fff;border-radius:18px;padding:28px;box-shadow:0 5px 18px rgba(34,61,49,.025);transition:.2s}.card:hover{box-shadow:var(--shadow);transform:translateY(-3px);border-color:#d7e2d8}.card-top{display:flex;justify-content:space-between;align-items:flex-start}.card-icon{width:49px;height:49px;border-radius:15px;background:var(--mint);display:grid;place-items:center;color:var(--green);font-size:22px}.arrow{font-size:20px;color:#a2aca5;transition:.18s}.card:hover .arrow{color:var(--green);transform:translate(2px,-2px)}.card h2{font-size:19px;letter-spacing:-.025em;margin:31px 0 7px}.card p{margin:0;color:var(--muted);font-size:13px;max-width:320px}.card-meta{position:absolute;bottom:25px;left:28px;font-size:12px;font-weight:650;color:var(--green)}.stat-strip{display:flex;align-items:center;gap:12px;margin-top:28px;padding:18px 22px;border:1px solid var(--line);background:#fff;border-radius:14px;color:var(--muted);font-size:13px}.stat-number{font-size:19px;font-weight:750;color:var(--ink)}.stat-dot{width:7px;height:7px;border-radius:50%;background:#76a888}.manage-grid{display:grid;grid-template-columns:minmax(290px,.8fr) minmax(0,1.2fr);gap:22px;align-items:start}.panel{background:#fff;border:1px solid var(--line);border-radius:16px;padding:25px;box-shadow:0 5px 18px rgba(34,61,49,.025)}.panel h2{font-size:17px;letter-spacing:-.025em;margin:0 0 5px}.panel-desc{font-size:13px;color:var(--muted);margin:0 0 23px}.field{margin-bottom:17px}.field label{display:block;font-size:12px;font-weight:680;margin-bottom:7px}.field input,.field textarea{display:block;width:100%;border:1px solid #dfe5de;background:#fff;border-radius:9px;padding:12px 13px;color:var(--ink);outline:none;transition:.15s}.field input:focus,.field textarea:focus{border-color:#7ba18b;box-shadow:0 0 0 3px rgba(91,137,106,.12)}.field textarea{min-height:112px;resize:vertical}.field ::placeholder{color:#a4aea6}.error{font-size:12px;color:var(--red);margin-top:5px}.success{background:#edf7ef;color:#28633e;border-radius:10px;padding:12px 15px;margin-bottom:18px;font-size:13px}.list-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:17px}.count-pill{background:#f1f4ef;color:#617268;border-radius:99px;padding:5px 10px;font-size:11px;font-weight:700}.kindergarten{padding:18px 0;border-top:1px solid var(--line);display:flex;gap:13px}.kindergarten:first-child{border-top:0;padding-top:0}.kindergarten-mark{width:36px;height:36px;flex:0 0 36px;background:#f4f1e8;border-radius:11px;display:grid;place-items:center;color:#8c7441}.kindergarten h3{font-size:14px;margin:1px 0 5px;line-height:1.35}.kindergarten p{white-space:pre-line;color:var(--muted);font-size:12px;margin:0}.empty{padding:38px 10px;text-align:center;color:var(--muted);font-size:13px}.empty-icon{font-size:25px;margin-bottom:10px;opacity:.72}.flash{background:#edf7ef;color:#28633e;border-radius:10px;padding:12px 15px;margin-bottom:19px;font-size:13px}.login-page{min-height:100vh;display:grid;grid-template-columns:1fr 1fr;background:#fff}.login-art{position:relative;overflow:hidden;background:#315d4f;display:flex;flex-direction:column;justify-content:space-between;padding:44px 54px;color:#fff}.art-orb{position:absolute;width:530px;height:530px;border-radius:50%;border:1px solid rgba(255,255,255,.13);right:-110px;top:19%;box-shadow:0 0 0 48px rgba(255,255,255,.035),0 0 0 100px rgba(255,255,255,.025)}.art-orb:before,.art-orb:after{content:"";position:absolute;border-radius:50%;border:1px solid rgba(255,255,255,.14);inset:75px}.art-orb:after{inset:155px;background:rgba(255,255,255,.04)}.art-brand{display:flex;gap:12px;align-items:center;z-index:1}.art-brand .brand-mark{background:rgba(255,255,255,.15)}.art-copy{position:relative;z-index:1;max-width:430px;margin-bottom:8vh}.art-copy h2{font-size:clamp(35px,4vw,54px);letter-spacing:-.05em;line-height:1.07;margin:15px 0}.art-copy p{color:rgba(255,255,255,.72);max-width:350px}.art-foot{position:relative;z-index:1;color:rgba(255,255,255,.55);font-size:11px}.login-side{display:grid;place-items:center;padding:30px}.login-box{width:min(390px,100%)}.login-box .brand{padding:0;margin-bottom:55px}.login-box h1{font-size:31px}.login-box>p{color:var(--muted);font-size:14px;margin:0 0 29px}.login-box .button{width:100%;margin-top:7px;padding:13px}.login-help{font-size:11px;color:#99a39d;text-align:center;margin-top:20px}.login-box .field input{padding:14px}.login-error{background:#fdf0ed;color:#a53d2e;border-radius:9px;padding:11px 13px;font-size:12px;margin-bottom:16px}
        .fields-row{display:grid;grid-template-columns:1fr 1fr;gap:12px}
        @media(max-width:850px){.shell{grid-template-columns:205px 1fr}.sidebar{padding:25px 13px}.manage-grid{grid-template-columns:1fr}.login-page{grid-template-columns:.8fr 1.2fr}.login-art{padding:35px 30px}.topbar{padding:0 24px}.content{padding-top:38px}}
        @media(max-width:620px){.shell{display:block}.sidebar{position:static;display:block;border-right:0;border-bottom:1px solid var(--line);padding:14px 18px}.brand{padding:0}.sidebar .nav-label,.sidebar-bottom{display:none}.sidebar .nav{display:flex;gap:4px;margin-top:15px}.nav a{padding:9px 10px;font-size:12px}.nav-icon{display:none}.topbar{height:68px}.top-eyebrow{display:none}.account-sub{display:none}.logout{margin-left:2px}.content{padding:31px 19px 48px}.intro{align-items:flex-start;flex-direction:column;margin-bottom:25px}.cards{grid-template-columns:1fr;gap:13px}.card{min-height:225px;padding:23px}.card h2{margin-top:25px}.card-meta{left:23px}.panel{padding:20px}.fields-row{grid-template-columns:1fr;gap:0}.login-page{display:block}.login-art{min-height:255px;padding:25px 24px}.art-orb{width:320px;height:320px;right:-160px;top:5%}.art-copy{margin:30px 0 0;max-width:330px}.art-copy h2{font-size:32px}.art-copy p{font-size:13px}.art-foot{display:none}.login-side{padding:40px 24px}.login-box .brand{margin-bottom:35px}}
    </style>
</head>
